- {"prov":[{"bbox":[139.34305,591.81409,476.01270000000005,622.30841],"page":1,"span":[0,222],"__ref_s3_data":null}],"text":"Maksym Lysak [0000 − 0002 − 3723 − $^{6960]}$, Ahmed Nassar[0000 − 0002 − 9468 − $^{0822]}$, Nikolaos Livathinos [0000 − 0001 − 8513 − $^{3491]}$, Christoph Auer[0000 − 0001 − 5761 − $^{0422]}$, [0000 − 0002 − 8088 − 0823]","type":"paragraph","payload":null,"name":"Text","font":null}
